// shared/rosterDiscovery.ts
var ROSTER_REMOVAL_STREAK = 2;
var MAP_PROMOTION_MIN_ROWS = 20;
var emptyRosterState = (evaluatedAt) => ({
  maps: [],
  brawlers: [],
  evaluatedAt
});
function normalize2(name2) {
  return name2.trim().toLowerCase();
}
function indexByName(entries2) {
  return new Map(entries2.map((entry) => [normalize2(entry.name), entry]));
}
function evaluateSection(kind, previous, reading, evidence, minimumRows, now) {
  const before = indexByName(previous);
  const presentKeys = new Set(reading.present.map(normalize2));
  const evidenceByName = new Map(evidence.map((item) => [normalize2(item.name), item]));
  const entries2 = [];
  const changes = [];
  for (const name2 of reading.present) {
    const key3 = normalize2(name2);
    const existing = before.get(key3);
    const support = evidenceByName.get(key3);
    const rows = support?.rows ?? 0;
    const missing = support?.missing ?? (rows >= minimumRows ? [] : ["estat\xEDsticas publicadas"]);
    const qualifies = rows >= minimumRows && missing.length === 0;
    if (!existing) {
      entries2.push({
        name: name2,
        status: qualifies ? "active" : "quarantine",
        absenceStreak: 0,
        firstSeenAt: now,
        lastSeenAt: now,
        ...qualifies ? { promotedAt: now } : { missing }
      });
      changes.push({
        kind,
        name: name2,
        change: "entered",
        detail: qualifies ? "com dados publicados" : `em quarentena \u2014 falta: ${missing.join(", ")}`
      });
      continue;
    }
    if (existing.status === "leaving") {
      entries2.push({ ...existing, status: existing.promotedAt ? "active" : "quarantine", absenceStreak: 0, lastSeenAt: now });
      changes.push({ kind, name: name2, change: "returned", detail: "voltou a ser publicado antes de sair" });
      continue;
    }
    if (existing.status === "quarantine" && qualifies) {
      entries2.push({ ...existing, status: "active", absenceStreak: 0, lastSeenAt: now, promotedAt: now, missing: void 0 });
      changes.push({ kind, name: name2, change: "promoted", detail: `${rows} linhas de dados` });
      continue;
    }
    entries2.push({
      ...existing,
      absenceStreak: 0,
      lastSeenAt: now,
      ...existing.status === "quarantine" ? { missing } : {}
    });
  }
  for (const existing of previous) {
    if (presentKeys.has(normalize2(existing.name))) continue;
    if (!reading.complete) {
      entries2.push(existing);
      continue;
    }
    const absenceStreak = existing.absenceStreak + 1;
    if (absenceStreak >= ROSTER_REMOVAL_STREAK) {
      changes.push({
        kind,
        name: existing.name,
        change: "removed",
        detail: `ausente em ${absenceStreak} leituras completas seguidas`
      });
      continue;
    }
    if (existing.status !== "leaving") {
      changes.push({ kind, name: existing.name, change: "leaving", detail: "deixou de ser publicado; confirma-se na pr\xF3xima leitura completa" });
    }
    entries2.push({ ...existing, status: "leaving", absenceStreak });
  }
  entries2.sort((left, right) => left.name.localeCompare(right.name, "pt-PT"));
  return { entries: entries2, changes };
}
function evaluateRoster(previous, input) {
  const now = input.now ?? (/* @__PURE__ */ new Date()).toISOString();
  const base = previous ?? emptyRosterState(now);
  const maps = input.maps ? evaluateSection("map", base.maps, input.maps, input.mapEvidence ?? [], MAP_PROMOTION_MIN_ROWS, now) : { entries: [...base.maps], changes: [] };
  const brawlers = input.brawlers ? evaluateSection("brawler", base.brawlers, input.brawlers, input.brawlerEvidence ?? [], 1, now) : { entries: [...base.brawlers], changes: [] };
  return {
    state: { maps: maps.entries, brawlers: brawlers.entries, evaluatedAt: now },
    changes: [...maps.changes, ...brawlers.changes]
  };
}

