import express from "express";
import fs2 from "fs";
import path2 from "path";

// server/_core/precompressedStatic.ts
import fs from "fs";
import path from "path";
var CONTENT_TYPES = {
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml",
  ".txt": "text/plain; charset=utf-8",
  ".map": "application/json; charset=utf-8",
  ".webmanifest": "application/manifest+json"
};
function servePrecompressed(distPath) {
  return (req, res, next) => {
    if (req.method !== "GET" && req.method !== "HEAD") return next();
    const accepted = String(req.headers["accept-encoding"] ?? "");
    const candidates = [];
    if (/\bbr\b/.test(accepted)) candidates.push({ encoding: "br", suffix: ".br" });
    if (/\bgzip\b/.test(accepted)) candidates.push({ encoding: "gzip", suffix: ".gz" });
    if (!candidates.length) return next();
    let pathname;
    try {
      pathname = decodeURIComponent(req.path);
    } catch {
      return next();
    }
    if (pathname.includes("\0")) return next();
    const original = path.join(distPath, pathname);
    if (!original.startsWith(distPath)) return next();
    const extension = path.extname(original);
    const contentType = CONTENT_TYPES[extension];
    if (!contentType) return next();
    for (const candidate of candidates) {
      const compressed = `${original}${candidate.suffix}`;
      const stat = fs.existsSync(compressed) ? fs.statSync(compressed) : null;
      if (!stat || !stat.isFile()) continue;
      res.setHeader("Content-Type", contentType);
      res.setHeader("Content-Encoding", candidate.encoding);
      res.setHeader("Content-Length", String(stat.size));
      res.setHeader("Vary", "Accept-Encoding");
      return res.sendFile(compressed, { acceptRanges: false }, (error) => {
        if (error) next(error);
      });
    }
    return next();
  };
}

// server/_core/static.ts
function serveStatic(app2) {
  const distPath = process.env.VERCEL === "1" ? path2.resolve(process.cwd(), "public") : process.env.NODE_ENV === "development" ? path2.resolve(import.meta.dirname, "../..", "dist", "public") : path2.resolve(import.meta.dirname, "public");
  if (!fs2.existsSync(distPath)) {
    console.error(
      `Could not find the build directory: ${distPath}, make sure to build the client first`
    );
  }
  app2.use(servePrecompressed(distPath));
  app2.use(express.static(distPath));
  app2.use("*", (_req, res) => {
    res.sendFile(path2.resolve(distPath, "index.html"));
  });
}

// server/scheduled.ts
async function handleRankedSyncScheduled(req, res) {
  let user;
  try {
    user = await sdk.authenticateRequest(req);
  } catch {
    return res.status(403).json({ error: "cron-only" });
  }
  try {
    if (!user.isCron || !user.taskUid) {
      return res.status(403).json({ error: "cron-only" });
    }
    const config = await getRankedSyncConfigByTaskUid(user.taskUid);
    if (!config) {
      return res.json({ ok: true, skipped: "orphan" });
    }
    const result = await syncRankedData("scheduled");
    if (!result.ok) {
      return res.status(500).json({
        error: result.error,
        context: { taskUid: user.taskUid, path: req.path },
        timestamp: (/* @__PURE__ */ new Date()).toISOString()
      });
    }
    return res.json({
      ok: true,
      trigger: "scheduled",
      version: result.version,
      rowCount: result.rowCount
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Erro desconhecido";
    return res.status(500).json({
      error: message,
      context: { path: req.path },
      timestamp: (/* @__PURE__ */ new Date()).toISOString()
    });
  }
}
