// server/observedMatchScheduled.ts
async function handleObservedMatchCollectionScheduled(req, res) {
  try {
    const user = await sdk.authenticateRequest(req);
    if (!user.isCron || !user.taskUid) return res.status(403).json({ error: "cron-only" });
    const config = await getObservedMatchCollectionConfigByTaskUid(user.taskUid);
    if (!config || !config.enabled) return res.json({ ok: true, skipped: "orphan-or-disabled" });
    const result = await collectObservedRankedMatches("scheduled");
    if (!result.ok) {
      return res.status(500).json({
        error: result.error,
        context: { taskUid: user.taskUid, path: req.path },
        timestamp: (/* @__PURE__ */ new Date()).toISOString()
      });
    }
    return res.json({ trigger: "scheduled", ...result });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Erro desconhecido";
    return res.status(500).json({ error: message, context: { path: req.path }, timestamp: (/* @__PURE__ */ new Date()).toISOString() });
  }
}

