// server/liveSync.ts
var DEFAULT_INTERVAL_MS = 15 * 60 * 1e3;
var MIN_INTERVAL_MS = 60 * 1e3;
var activeCycle;
function readIntervalMs() {
  const configured = Number(process.env.BRAWL_LIVE_SYNC_INTERVAL_MS ?? DEFAULT_INTERVAL_MS);
  if (!Number.isFinite(configured)) return DEFAULT_INTERVAL_MS;
  return Math.max(MIN_INTERVAL_MS, Math.floor(configured));
}
function isLiveSyncEnabled() {
  return process.env.BRAWL_LIVE_SYNC_ENABLED === "true";
}
function getLiveSyncState() {
  return {
    enabled: isLiveSyncEnabled(),
    rankedEnabled: isLiveSyncEnabled() || process.env.BRAWL_RANKED_SYNC_ENABLED !== "false",
    intervalMs: readIntervalMs(),
    running: Boolean(activeCycle)
  };
}

// server/_core/index.vercel.ts
function createApp() {
  const app2 = express2();
  const server2 = createServer(app2);
  app2.use(express2.json({ limit: "50mb" }));
  app2.use(express2.urlencoded({ limit: "50mb", extended: true }));
  registerStorageProxy(app2);
  registerOAuthRoutes(app2);
  app2.post("/api/scheduled/rankedSync", handleRankedSyncScheduled);
  app2.post("/api/scheduled/counterSync", handleCounterSyncScheduled);
  app2.post("/api/scheduled/observedMatchCollection", handleObservedMatchCollectionScheduled);
  app2.get("/api/realtime/status", (_req, res) => res.json(getLiveSyncState()));
  app2.get("/api/realtime/ranked", async (_req, res) => {
    res.status(200).set({
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
      "X-Accel-Buffering": "no"
    });
    res.flushHeaders();
    let disconnected = false;
    res.once("close", () => {
      disconnected = true;
    });
    const snapshot = await getPublicRankedSnapshot();
    if (disconnected) return;
    const capturedAt = snapshot.capturedAt ? new Date(snapshot.capturedAt) : null;
    res.write(`event: ranked_snapshot
data: ${JSON.stringify({
      version: snapshot.version,
      capturedAt: snapshot.capturedAt,
      syncState: snapshot.version === "bundled-static" ? "bundled" : "success",
      nextRefreshAt: getNextRefreshAt(capturedAt)?.toISOString() ?? null,
      sourceStatus: snapshot.sourceStatus,
      sourceNotes: snapshot.sourceNotes,
      rowCount: snapshot.rowCount,
      payload: snapshot.payload
    })}

`);
    const removeClient = addRankedClient(res);
    const heartbeat = setInterval(() => res.write(": heartbeat\n\n"), 25e3);
    res.on("close", () => {
      clearInterval(heartbeat);
      removeClient();
    });
  });
  app2.get("/api/realtime/counters", async (_req, res) => {
    res.status(200).set({
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
      "X-Accel-Buffering": "no"
    });
    res.flushHeaders();
    let disconnected = false;
    res.once("close", () => {
      disconnected = true;
    });
    const snapshot = await getPublicCounterSyncSnapshot();
    if (disconnected) return;
    if (snapshot) res.write(`event: counter_snapshot
data: ${JSON.stringify({ version: snapshot.version, capturedAt: snapshot.capturedAt, payload: snapshot.payload })}

`);
    const removeClient = addCounterClient(res);
    const heartbeat = setInterval(() => res.write(": heartbeat\n\n"), 25e3);
    res.on("close", () => {
      clearInterval(heartbeat);
      removeClient();
    });
  });
  app2.use("/api/trpc", createExpressMiddleware({ router: appRouter, createContext }));
  serveStatic(app2);
  return { app: app2, server: server2 };
}
var { app, server } = createApp();
if (!process.env.VERCEL) {
  const port = parseInt(process.env.PORT || "3000", 10);
  server.listen(port, () => {
    console.log(`[Brawl H\xEDbrido] Vers\xE3o ${VERSAO_DO_SITE} em execu\xE7\xE3o.`);
    console.log(`Server running on http://localhost:${port}/`);
  });
}
process.on("unhandledRejection", (motivo) => console.error("[Processo] Promessa rejeitada sem tratamento; o servidor continua ativo:", motivo));
process.on("uncaughtException", (erro) => console.error("[Processo] Exce\xE7\xE3o n\xE3o tratada; o servidor continua ativo:", erro));
var index_vercel_default = app;
export {
  app,
  createApp,
  index_vercel_default as default,
  server
};
